import itertools

# Let's try to construct a maximal triangle-free graph
# We'll use the complete bipartite approach

n = 20
fixed_edges = [(1,18), (4,18), (16,18), (4,19), (17,18), (11,19), (3,19)]

# Let's figure out a valid bipartition
# From the fixed edges:
# 1-18, 4-18, 16-18, 17-18: 1,4,16,17 are opposite to 18
# 4-19, 11-19, 3-19: 4,11,3 are opposite to 19
# Since 4 is opposite both 18 and 19, 18 and 19 are on the same side

# Let's try: side0 = {18, 19, ...}, side1 = {1, 3, 4, 11, 16, 17, ...}

# We need to assign all 20 vertices to two sides
# All edges between sides are present, no edges within sides

# Let's try a balanced partition
side0 = {18, 19}
side1 = {1, 3, 4, 11, 16, 17}

# Remaining vertices: 0,2,5,6,7,8,9,10,12,13,14,15
remaining = set(range(20)) - side0 - side1
print("Remaining:", sorted(remaining))

# Let's try to make it balanced: 10 and 10
# side0 has 2, side1 has 6
# We need 8 more in side0 and 4 more in side1 to make 10 each
# Or we can do any split

# Let's just put all remaining in side0
side0 = side0 | remaining
print("Side0:", sorted(side0))
print("Side1:", sorted(side1))
print("Sizes:", len(side0), len(side1))

# Generate all edges between side0 and side1
edges = []
for u in side0:
    for v in side1:
        if u < v:
            edges.append((u, v))
        else:
            edges.append((v, u))

edges = sorted(set(edges))
print("Number of edges:", len(edges))

# Verify fixed edges are present
for e in fixed_edges:
    u, v = e
    if u > v:
        u, v = v, u
    if (u, v) not in edges:
        print(f"Missing fixed edge: {e}")
    else:
        print(f"Fixed edge {e} is present")

# Verify triangle-free
def has_triangle(edges_set):
    for i in range(20):
        for j in range(i+1, 20):
            if (i, j) in edges_set:
                for k in range(j+1, 20):
                    if (i, k) in edges_set and (j, k) in edges_set:
                        return (i, j, k)
    return None

edges_set = set(edges)
tri = has_triangle(edges_set)
print("Triangle found:", tri)

# Verify maximal
def is_maximal(edges_set, n):
    for i in range(n):
        for j in range(i+1, n):
            if (i, j) not in edges_set:
                # Check if adding (i,j) creates a triangle
                found = False
                for k in range(n):
                    if k != i and k != j:
                        if ((i, k) in edges_set and (j, k) in edges_set):
                            found = True
                            break
                if not found:
                    return False, (i, j)
    return True, None

maximal, missing = is_maximal(edges_set, n)
print("Maximal:", maximal)
if not maximal:
    print("Missing edge that doesn't create triangle:", missing)

